    VkBuffer readback_ = VK_NULL_HANDLE;
    VkDeviceMemory readback_memory_ = VK_NULL_HANDLE;
    VkBuffer readback_alt_ = VK_NULL_HANDLE;
    VkDeviceMemory readback_memory_alt_ = VK_NULL_HANDLE;
